Pattern captures = Pattern.compile('([A-Z]+)([0-9]+)');
Matcher all = captures.matcher('A1 B22');
System.assertEquals('A0 B0', all.replaceAll('$10'));
Matcher first = captures.matcher('A1 B22');
System.assertEquals('$1 B22', first.replaceFirst('\$1'));

